package cl.duoc.biblioteca.dao;
import cl.duoc.biblioteca.database.DatabaseConnection;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;
public class BibliotecaDAO {
 public List<Object[]> libros() throws SQLException {return query("SELECT l.id,l.titulo,l.autor,l.isbn,l.editorial,l.stock,c.nombre FROM libros l LEFT JOIN categorias c ON c.id=l.id_categoria ORDER BY l.id");}
 public List<Object[]> estudiantes() throws SQLException {return query("SELECT id,nombre,rut,curso,correo FROM estudiantes ORDER BY id");}
 public List<Object[]> prestamos() throws SQLException {return query("SELECT p.id,e.nombre,l.titulo,p.fecha_prestamo,p.fecha_devolucion,IF(p.devuelto,'Sí','No'),IF(p.devuelto,'Devuelto',IF(CURDATE()>p.fecha_devolucion,'Atrasado','Vigente')) FROM prestamos p JOIN estudiantes e ON e.id=p.id_estudiante JOIN libros l ON l.id=p.id_libro ORDER BY p.id DESC");}
 public List<Object[]> reporte(String tipo) throws SQLException {String sql=switch(tipo){case "Más prestados"->"SELECT l.titulo,COUNT(*) AS prestamos FROM prestamos p JOIN libros l ON l.id=p.id_libro GROUP BY l.id,l.titulo ORDER BY prestamos DESC";case "Préstamos activos"->"SELECT e.nombre,l.titulo,p.fecha_prestamo,p.fecha_devolucion FROM prestamos p JOIN estudiantes e ON e.id=p.id_estudiante JOIN libros l ON l.id=p.id_libro WHERE p.devuelto=FALSE ORDER BY p.fecha_devolucion";default->"SELECT e.nombre,l.titulo,p.fecha_prestamo,p.fecha_devolucion,IF(p.devuelto,'Sí','No') FROM prestamos p JOIN estudiantes e ON e.id=p.id_estudiante JOIN libros l ON l.id=p.id_libro ORDER BY e.nombre,p.fecha_prestamo DESC";};return query(sql);}
 private List<Object[]> query(String sql)throws SQLException{List<Object[]> out=new ArrayList<>();try(Connection c=DatabaseConnection.getInstance().getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){int n=r.getMetaData().getColumnCount();while(r.next()){Object[] row=new Object[n];for(int i=0;i<n;i++)row[i]=r.getObject(i+1);out.add(row);}}return out;}
 public List<String> categorias() throws SQLException {List<String> a=new ArrayList<>();try(Connection c=DatabaseConnection.getInstance().getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,nombre FROM categorias ORDER BY id")){while(r.next())a.add(r.getInt(1)+" - "+r.getString(2));}return a;}
 public synchronized void guardarLibro(Integer id,String titulo,String autor,String isbn,String editorial,int stock,int categoria)throws SQLException{if(stock<0)throw new SQLException("El stock no puede ser negativo.");String sql=id==null?"INSERT INTO libros(titulo,autor,isbn,editorial,stock,id_categoria) VALUES(?,?,?,?,?,?)":"UPDATE libros SET titulo=?,autor=?,isbn=?,editorial=?,stock=?,id_categoria=? WHERE id=?";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,titulo);p.setString(2,autor);p.setString(3,isbn);p.setString(4,editorial);p.setInt(5,stock);p.setInt(6,categoria);if(id!=null)p.setInt(7,id);p.executeUpdate();}}
 public void eliminarLibro(int id)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM libros WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}
 public void guardarEstudiante(Integer id,String nombre,String rut,String curso,String correo)throws SQLException{String sql=id==null?"INSERT INTO estudiantes(nombre,rut,curso,correo) VALUES(?,?,?,?)":"UPDATE estudiantes SET nombre=?,rut=?,curso=?,correo=? WHERE id=?";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,nombre);p.setString(2,rut);p.setString(3,curso);p.setString(4,correo);if(id!=null)p.setInt(5,id);p.executeUpdate();}}
 public void eliminarEstudiante(int id)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM estudiantes WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}
 public synchronized void prestar(int estudiante,int libro)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection()){c.setAutoCommit(false);try{int stock;try(PreparedStatement p=c.prepareStatement("SELECT stock FROM libros WHERE id=? FOR UPDATE")){p.setInt(1,libro);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Libro no encontrado.");stock=r.getInt(1);}}if(stock<=0)throw new SQLException("No hay ejemplares disponibles.");try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock-1 WHERE id=? AND stock>0")){p.setInt(1,libro);if(p.executeUpdate()!=1)throw new SQLException("No queda stock disponible.");}try(PreparedStatement p=c.prepareStatement("INSERT INTO prestamos(id_estudiante,id_libro,fecha_prestamo,fecha_devolucion,devuelto) VALUES(?,?,?, ?,FALSE)")){p.setInt(1,estudiante);p.setInt(2,libro);p.setDate(3,java.sql.Date.valueOf(LocalDate.now()));p.setDate(4,java.sql.Date.valueOf(LocalDate.now().plusDays(7)));p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public void devolver(int prestamo)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection()){c.setAutoCommit(false);try{int libro;try(PreparedStatement p=c.prepareStatement("SELECT id_libro FROM prestamos WHERE id=? AND devuelto=FALSE FOR UPDATE")){p.setInt(1,prestamo);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Préstamo inexistente o ya devuelto.");libro=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("UPDATE prestamos SET devuelto=TRUE WHERE id=?")){p.setInt(1,prestamo);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock+1 WHERE id=?")){p.setInt(1,libro);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
}
